<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu-ish Desktop</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { height: 100%; overflow: hidden; }
  body {
    font-family: "Ubuntu", "Segoe UI", system-ui, sans-serif;
    color: #f4f1ee;
    user-select: none;
  }

  /* ---------- Desktop ---------- */
  #desktop {
    position: fixed;
    inset: 0;
    background:
      radial-gradient(1200px 700px at 75% 15%, #5b2a4a 0%, rgba(91,42,74,0) 60%),
      radial-gradient(1000px 800px at 15% 85%, #7a3b1e 0%, rgba(122,59,30,0) 55%),
      linear-gradient(135deg, #2c001e 0%, #3a0f2a 45%, #401a10 100%);
    overflow: hidden;
  }

  /* Subtle desktop icons area */
  #desktop-icons {
    position: absolute;
    top: 20px; left: 20px;
    display: flex; flex-direction: column; gap: 22px;
  }
  .desk-icon {
    width: 74px; text-align: center; cursor: default; opacity: .9;
  }
  .desk-icon .glyph {
    width: 52px; height: 52px; margin: 0 auto 4px;
    display: flex; align-items: center; justify-content: center;
    font-size: 26px; border-radius: 12px;
    background: rgba(255,255,255,.08);
    border: 1px solid rgba(255,255,255,.12);
  }
  .desk-icon .lbl { font-size: 12px; text-shadow: 0 1px 2px rgba(0,0,0,.6); }

  /* ---------- Top bar ---------- */
  #topbar {
    position: absolute; top: 0; left: 0; right: 0; height: 28px;
    background: rgba(20, 8, 16, .85);
    backdrop-filter: blur(6px);
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 14px; font-size: 13px; z-index: 5000;
    border-bottom: 1px solid rgba(255,255,255,.06);
  }
  #topbar .activities { font-weight: 600; opacity: .9; }
  #topbar .clock { opacity: .85; }

  /* ---------- Taskbar / dock ---------- */
  #taskbar {
    position: absolute; top: 44px; left: 10px;
    width: 60px;
    background: rgba(20, 8, 16, .78);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 16px;
    padding: 10px 6px; z-index: 4000;
    display: flex; flex-direction: column; gap: 12px;
  }
  .launcher {
    width: 48px; height: 48px; border: none; cursor: pointer;
    border-radius: 12px; font-size: 24px; color: #fff;
    display: flex; align-items: center; justify-content: center;
    background: linear-gradient(160deg, #ff7043, #e64a19);
    box-shadow: 0 3px 8px rgba(0,0,0,.35);
    transition: transform .08s ease, filter .12s ease;
    position: relative;
  }
  .launcher:hover { filter: brightness(1.12); transform: translateY(-1px); }
  .launcher:active { transform: translateY(0) scale(.96); }
  #open-notepad { background: linear-gradient(160deg, #5c6bc0, #3949ab); }
  .launcher.running::after {
    content: ""; position: absolute; left: -4px; top: 50%;
    transform: translateY(-50%);
    width: 4px; height: 20px; border-radius: 2px; background: #ff7043;
  }
  #open-notepad.running::after { background: #7986cb; }

  /* ---------- Windows ---------- */
  .window {
    position: absolute;
    min-width: 360px; min-height: 240px;
    background: #2b2226;
    border: 1px solid rgba(255,255,255,.10);
    border-radius: 10px;
    box-shadow: 0 18px 50px rgba(0,0,0,.55);
    display: none;
    flex-direction: column;
    overflow: hidden;
    z-index: 100;
  }
  .window.show { display: flex; }

  .titlebar {
    height: 38px; flex: 0 0 38px;
    background: linear-gradient(180deg, #3a2f34, #2f2529);
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 10px; cursor: grab;
    border-bottom: 1px solid rgba(0,0,0,.35);
  }
  .titlebar.dragging { cursor: grabbing; }
  .titlebar .title { font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 8px; }
  .win-btns { display: flex; gap: 8px; }
  .win-btn {
    width: 15px; height: 15px; border-radius: 50%; border: none; cursor: pointer;
    padding: 0;
  }
  .win-min { background: #f5c542; }
  .win-close { background: #ff5f57; }
  .win-btn:hover { filter: brightness(1.15); }

  .win-body { flex: 1 1 auto; display: flex; min-height: 0; }

  /* ---------- Files app ---------- */
  #files-window { width: 640px; height: 440px; top: 90px; left: 140px; }
  .files-sidebar {
    width: 150px; flex: 0 0 150px; background: #241c20;
    border-right: 1px solid rgba(255,255,255,.06);
    padding: 10px 8px; font-size: 13px; overflow: auto;
  }
  .files-sidebar .sb-title { opacity: .55; font-size: 11px; text-transform: uppercase; margin: 4px 6px 6px; letter-spacing: .5px; }
  .sb-link {
    padding: 6px 8px; border-radius: 6px; cursor: pointer;
    display: flex; align-items: center; gap: 8px;
  }
  .sb-link:hover { background: rgba(255,255,255,.07); }
  .files-main { flex: 1 1 auto; display: flex; flex-direction: column; min-width: 0; }
  .files-toolbar {
    display: flex; align-items: center; gap: 8px;
    padding: 8px 10px; border-bottom: 1px solid rgba(255,255,255,.06);
    background: #2b2226;
  }
  .tool-btn {
    background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.10);
    color: #f4f1ee; border-radius: 6px; padding: 5px 10px; cursor: pointer; font-size: 13px;
  }
  .tool-btn:hover { background: rgba(255,255,255,.15); }
  .tool-btn:disabled { opacity: .4; cursor: default; }
  #files-path {
    flex: 1 1 auto; font-family: "Ubuntu Mono", monospace; font-size: 13px;
    background: #1d1619; border: 1px solid rgba(255,255,255,.08);
    border-radius: 6px; padding: 6px 10px; overflow: auto; white-space: nowrap;
  }
  .files-list {
    flex: 1 1 auto; overflow: auto; padding: 12px;
    display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr));
    gap: 10px; align-content: start;
  }
  .fs-item {
    display: flex; flex-direction: column; align-items: center; gap: 6px;
    padding: 10px 6px; border-radius: 8px; cursor: default; text-align: center;
    border: 1px solid transparent;
  }
  .fs-item:hover { background: rgba(255,255,255,.06); }
  .fs-item.selected { background: rgba(255,112,67,.22); border-color: rgba(255,112,67,.5); }
  .fs-item .ic { font-size: 30px; line-height: 1; }
  .fs-item .nm { font-size: 12px; word-break: break-word; max-width: 88px; }
  .files-status {
    flex: 0 0 24px; font-size: 12px; opacity: .6; padding: 3px 12px;
    border-top: 1px solid rgba(255,255,255,.06);
  }

  /* ---------- Notepad app ---------- */
  #notepad-window { width: 560px; height: 420px; top: 130px; left: 340px; }
  .notepad-main { flex: 1 1 auto; display: flex; flex-direction: column; min-width: 0; }
  #tabs {
    display: flex; align-items: stretch; gap: 4px; padding: 6px 6px 0;
    background: #241c20; overflow-x: auto; min-height: 40px;
  }
  .tab {
    display: flex; align-items: center; gap: 6px;
    padding: 7px 10px; border-radius: 8px 8px 0 0; cursor: pointer;
    background: rgba(255,255,255,.05); font-size: 13px; white-space: nowrap;
    max-width: 180px; border: 1px solid transparent; border-bottom: none;
  }
  .tab .tab-name { overflow: hidden; text-overflow: ellipsis; }
  .tab.active { background: #2b2226; border-color: rgba(255,255,255,.10); }
  .tab .tab-close {
    border: none; background: transparent; color: #ccc; cursor: pointer;
    font-size: 14px; line-height: 1; padding: 0 2px; border-radius: 4px;
  }
  .tab .tab-close:hover { background: rgba(255,255,255,.15); color: #fff; }
  #new-tab {
    flex: 0 0 auto; width: 30px; border: none; cursor: pointer;
    background: rgba(255,255,255,.07); color: #fff; font-size: 18px;
    border-radius: 8px 8px 0 0; align-self: stretch;
  }
  #new-tab:hover { background: rgba(255,255,255,.15); }
  #editor {
    flex: 1 1 auto; resize: none; border: none; outline: none;
    background: #221a1e; color: #f4f1ee; padding: 14px;
    font-family: "Ubuntu Mono", ui-monospace, monospace; font-size: 14px;
    line-height: 1.5; min-height: 0;
  }
  .notepad-status {
    flex: 0 0 24px; font-size: 12px; opacity: .6; padding: 3px 12px;
    border-top: 1px solid rgba(255,255,255,.06);
  }
</style>
</head>
<body>
<div id="desktop">

  <div id="topbar">
    <span class="activities">Activities</span>
