  </div>

  <div id="desktop-icons">
    <div class="desk-icon" data-app="files">
      <div class="glyph">📁</div><div class="lbl">Files</div>
    </div>
    <div class="desk-icon" data-app="notepad">
      <div class="glyph">📝</div><div class="lbl">Notepad</div>
