    <div class="win-body">
      <div class="files-sidebar">
        <div class="sb-title">Places</div>
        <div class="sb-link" data-go="/">🏠 Root</div>
        <div class="sb-link" data-go="/home/user">👤 Home</div>
        <div class="sb-link" data-go="/home/user/Documents">📄 Documents</div>
        <div class="sb-link" data-go="/home/user/Downloads">⬇️ Downloads</div>
        <div class="sb-link" data-go="/home/user/Pictures">🖼️ Pictures</div>
