</div>

<script>
(function () {
  "use strict";

  /* ============================================================
     Fake filesystem (static data)
     ============================================================ */
  // Each node: { name, type: 'dir'|'file', children? }
  const FS = {
    name: "/", type: "dir", children: [
      { name: "bin", type: "dir", children: [
        { name: "bash", type: "file" }, { name: "ls", type: "file" },
        { name: "cat", type: "file" }, { name: "grep", type: "file" },
      ]},
      { name: "etc", type: "dir", children: [
        { name: "hostname", type: "file" }, { name: "passwd", type: "file" },
        { name: "fstab", type: "file" },
        { name: "network", type: "dir", children: [
          { name: "interfaces", type: "file" },
        ]},
      ]},
      { name: "home", type: "dir", children: [
        { name: "user", type: "dir", children: [
          { name: "Documents", type: "dir", children: [
            { name: "resume.pdf", type: "file" },
            { name: "notes.txt", type: "file" },
            { name: "Projects", type: "dir", children: [
              { name: "brassworks", type: "dir", children: [
                { name: "README.md", type: "file" },
              ]},
            ]},
          ]},
          { name: "Downloads", type: "dir", children: [
            { name: "ubuntu-24.04.iso", type: "file" },
            { name: "photo.jpg", type: "file" },
          ]},
          { name: "Pictures", type: "dir", children: [
            { name: "wallpaper.png", type: "file" },
            { name: "screenshot.png", type: "file" },
          ]},
          { name: ".bashrc", type: "file" },
          { name: "todo.txt", type: "file" },
        ]},
      ]},
      { name: "usr", type: "dir", children: [
        { name: "bin", type: "dir", children: [
          { name: "python3", type: "file" }, { name: "node", type: "file" },
        ]},
        { name: "lib", type: "dir", children: [] },
        { name: "share", type: "dir", children: [
          { name: "applications", type: "dir", children: [] },
        ]},
      ]},
      { name: "var", type: "dir", children: [
        { name: "log", type: "dir", children: [
          { name: "syslog", type: "file" }, { name: "auth.log", type: "file" },
        ]},
        { name: "tmp", type: "dir", children: [] },
        { name: "www", type: "dir", children: [
          { name: "index.html", type: "file" },
        ]},
      ]},
    ]
  };

  // Resolve an absolute path string to a node (or null).
  function resolvePath(path) {
    if (path === "/" || path === "") return FS;
    const parts = path.split("/").filter(Boolean);
    let node = FS;
    for (const part of parts) {
      if (node.type !== "dir" || !node.children) return null;
      const next = node.children.find(c => c.name === part);
      if (!next) return null;
      node = next;
    }
    return node;
  }

  function joinPath(path, name) {
    return path === "/" ? "/" + name : path + "/" + name;
  }
  function parentPath(path) {
    if (path === "/" ) return "/";
    const parts = path.split("/").filter(Boolean);
    parts.pop();
    return "/" + parts.join("/");
  }

  const iconFor = (node) => {
    if (node.type === "dir") return "📁";
    const n = node.name.toLowerCase();
    if (n.endsWith(".png") || n.endsWith(".jpg") || n.endsWith(".jpeg") || n.endsWith(".gif")) return "🖼️";
    if (n.endsWith(".pdf")) return "📕";
    if (n.endsWith(".txt") || n.endsWith(".md")) return "📄";
    if (n.endsWith(".iso")) return "💿";
    if (n.endsWith(".log")) return "🧾";
    if (n.startsWith(".")) return "⚙️";
    return "📄";
  };

  /* ============================================================
     Window management (open / close / focus / drag)
     ============================================================ */
  let zTop = 100;
  function focusWindow(win) { win.style.zIndex = String(++zTop); }

  function openWindow(win, launcher) {
    win.classList.add("show");
    focusWindow(win);
    if (launcher) launcher.classList.add("running");
  }
  function closeWindow(win, launcher) {
    win.classList.remove("show");
    if (launcher) launcher.classList.remove("running");
  }

  function makeDraggable(win) {
    const bar = win.querySelector(".titlebar");
    let dragging = false, offX = 0, offY = 0;
    bar.addEventListener("mousedown", (e) => {
      if (e.target.closest(".win-btn")) return;
      dragging = true;
      bar.classList.add("dragging");
      const rect = win.getBoundingClientRect();
      offX = e.clientX - rect.left;
      offY = e.clientY - rect.top;
      focusWindow(win);
      e.preventDefault();
    });
    document.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      let x = e.clientX - offX;
      let y = e.clientY - offY;
      // keep within viewport-ish bounds
      x = Math.max(-win.offsetWidth + 80, Math.min(x, window.innerWidth - 80));
      y = Math.max(28, Math.min(y, window.innerHeight - 40));
      win.style.left = x + "px";
      win.style.top = y + "px";
    });
    document.addEventListener("mouseup", () => {
      dragging = false; bar.classList.remove("dragging");
    });
    win.addEventListener("mousedown", () => focusWindow(win));
  }

  const filesWindow = document.getElementById("files-window");
  const notepadWindow = document.getElementById("notepad-window");
  const openFilesBtn = document.getElementById("open-files");
  const openNotepadBtn = document.getElementById("open-notepad");

  makeDraggable(filesWindow);
  makeDraggable(notepadWindow);

  openFilesBtn.addEventListener("click", () => openWindow(filesWindow, openFilesBtn));
  openNotepadBtn.addEventListener("click", () => openWindow(notepadWindow, openNotepadBtn));

  // Desktop icons also launch
  document.querySelectorAll(".desk-icon").forEach(ic => {
    ic.addEventListener("dblclick", () => {
      if (ic.dataset.app === "files") openWindow(filesWindow, openFilesBtn);
      else openWindow(notepadWindow, openNotepadBtn);
    });
  });

  // Close buttons
  filesWindow.querySelector(".win-close").addEventListener("click",
    () => closeWindow(filesWindow, openFilesBtn));
  notepadWindow.querySelector(".win-close").addEventListener("click",
    () => closeWindow(notepadWindow, openNotepadBtn));
  // Minimize == just hide (keeps state)
  filesWindow.querySelector(".win-min").addEventListener("click",
    () => closeWindow(filesWindow, openFilesBtn));
  notepadWindow.querySelector(".win-min").addEventListener("click",
    () => closeWindow(notepadWindow, openNotepadBtn));

  /* ============================================================
     Files app logic
     ============================================================ */
  const filesPathEl = document.getElementById("files-path");
  const filesListEl = document.getElementById("files-list");
  const filesUpBtn = document.getElementById("files-up");
  const filesStatusEl = document.getElementById("files-status");
  let currentPath = "/";

  function renderFiles(path) {
    const node = resolvePath(path);
    if (!node || node.type !== "dir") return;
    currentPath = path;
    filesPathEl.textContent = path;
    filesUpBtn.disabled = (path === "/");

    filesListEl.innerHTML = "";
    const children = (node.children || []).slice().sort((a, b) => {
      if (a.type !== b.type) return a.type === "dir" ? -1 : 1;
      return a.name.localeCompare(b.name);
    });

    for (const child of children) {
      const item = document.createElement("div");
      item.className = "fs-item";
      item.dataset.type = child.type;
      item.dataset.name = child.name;

      const ic = document.createElement("div");
      ic.className = "ic";
      ic.textContent = iconFor(child);

      const nm = document.createElement("div");
      nm.className = "nm";
      nm.textContent = child.name;

      item.appendChild(ic);
      item.appendChild(nm);

      item.addEventListener("click", () => {
        filesListEl.querySelectorAll(".fs-item.selected")
          .forEach(el => el.classList.remove("selected"));
        item.classList.add("selected");
      });
      item.addEventListener("dblclick", () => {
        if (child.type === "dir") {
          renderFiles(joinPath(path, child.name));
        } else {
          filesStatusEl.textContent = 'Cannot open "' + child.name + '" — no application associated.';
        }
      });

      filesListEl.appendChild(item);
    }

    const dirs = children.filter(c => c.type === "dir").length;
    const files = children.filter(c => c.type === "file").length;
    filesStatusEl.textContent = dirs + " folder" + (dirs === 1 ? "" : "s") +
      ", " + files + " file" + (files === 1 ? "" : "s");
  }

  filesUpBtn.addEventListener("click", () => {
    if (currentPath !== "/") renderFiles(parentPath(currentPath));
  });

  document.querySelectorAll(".sb-link").forEach(link => {
    link.addEventListener("click", () => {
      const dest = link.dataset.go;
      if (resolvePath(dest)) renderFiles(dest);
    });
  });

  renderFiles("/");

  /* ============================================================
     Notepad app logic (persistent, tabbed)
     ============================================================ */
  const STORAGE_KEY = "ubuntu_notepad_state_v1";
  const tabsEl = document.getElementById("tabs");
  const newTabBtn = document.getElementById("new-tab");
  const editorEl = document.getElementById("editor");
  const notepadStatusEl = document.getElementById("notepad-status");

  let state = { tabs: [], activeId: null, seq: 1 };

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.tabs)) state = parsed;
      }
    } catch (e) { /* corrupt storage — fall through to defaults */ }

    if (!state.tabs || state.tabs.length === 0) {
      state = { tabs: [], activeId: null, seq: 1 };
      createTab("Welcome",
        "Welcome to Notepad!\n\nYour tabs and text are saved automatically to " +
        "localStorage, so they'll still be here after you close this window or " +
        "reload the page.\n\nClick + to add a tab.");
    }
    if (!state.tabs.some(t => t.id === state.activeId)) {
      state.activeId = state.tabs[0].id;
    }
  }

  function saveState() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
    catch (e) { /* storage full/unavailable — ignore */ }
  }

  function createTab(name, content) {
    const id = "t" + (state.seq++);
    const tab = { id: id, name: name || ("Untitled " + (state.tabs.length + 1)), content: content || "" };
    state.tabs.push(tab);
    state.activeId = id;
    saveState();
    return tab;
  }

  function activeTab() {
    return state.tabs.find(t => t.id === state.activeId) || null;
  }

  function renderTabs() {
    // remove existing tab elements (keep the + button)
    tabsEl.querySelectorAll(".tab").forEach(el => el.remove());

    state.tabs.forEach(tab => {
      const el = document.createElement("div");
      el.className = "tab" + (tab.id === state.activeId ? " active" : "");
      el.dataset.id = tab.id;

      const nameEl = document.createElement("span");
      nameEl.className = "tab-name";
      nameEl.textContent = tab.name;

      const closeBtn = document.createElement("button");
      closeBtn.className = "tab-close";
      closeBtn.textContent = "×";
      closeBtn.title = "Close tab";
      closeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        closeTab(tab.id);
      });

      el.appendChild(nameEl);
      el.appendChild(closeBtn);
      el.addEventListener("click", () => setActive(tab.id));

      tabsEl.insertBefore(el, newTabBtn);
    });
  }

  function renderEditor() {
    const tab = activeTab();
    if (tab) {
      editorEl.disabled = false;
      editorEl.value = tab.content;
      notepadStatusEl.textContent = tab.content.length + " chars · " +
        (tab.content ? tab.content.split(/\n/).length : 0) + " lines";
    } else {
      editorEl.value = "";
      editorEl.disabled = true;
      notepadStatusEl.textContent = "No tabs open";
    }
  }

  function renderNotepad() { renderTabs(); renderEditor(); }

  function setActive(id) {
    state.activeId = id;
    saveState();
    renderNotepad();
  }

  function closeTab(id) {
    const idx = state.tabs.findIndex(t => t.id === id);
    if (idx === -1) return;
    state.tabs.splice(idx, 1);
    if (state.activeId === id) {
      const fallback = state.tabs[idx] || state.tabs[idx - 1] || state.tabs[0];
      state.activeId = fallback ? fallback.id : null;
    }
    if (state.tabs.length === 0) {
      createTab("Untitled 1", "");
    }
    saveState();
    renderNotepad();
  }

  newTabBtn.addEventListener("click", () => {
    createTab("Untitled " + (state.tabs.length + 1), "");
    renderNotepad();
    editorEl.focus();
  });

  editorEl.addEventListener("input", () => {
    const tab = activeTab();
    if (!tab) return;
    tab.content = editorEl.value;
    // Derive a friendly tab name from the first non-empty line for untitled tabs.
    if (/^Untitled /.test(tab.name)) {
      const firstLine = editorEl.value.split(/\n/)[0].trim();
      if (firstLine) tab.name = firstLine.slice(0, 20);
    }
    notepadStatusEl.textContent = editorEl.value.length + " chars · " +
      (editorEl.value ? editorEl.value.split(/\n/).length : 0) + " lines";
    renderTabsNameOnly();
    saveState();
  });

  // Lightweight tab-name refresh without rebuilding the whole strip on each keystroke.
  function renderTabsNameOnly() {
    tabsEl.querySelectorAll(".tab").forEach(el => {
      const tab = state.tabs.find(t => t.id === el.dataset.id);
      if (tab) {
        const nameEl = el.querySelector(".tab-name");
        if (nameEl && nameEl.textContent !== tab.name) nameEl.textContent = tab.name;
      }
    });
  }

  loadState();
  renderNotepad();

  // Sync across other tabs/windows of the same page.
  window.addEventListener("storage", (e) => {
    if (e.key === STORAGE_KEY) { loadState(); renderNotepad(); }
  });

  /* ============================================================
     Clock
     ============================================================ */
  const clockEl = document.getElementById("clock");
  function tickClock() {
    const d = new Date();
    const days = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
    const mm = String(d.getMinutes()).padStart(2, "0");
    let h = d.getHours();
    const ap = h >= 12 ? "PM" : "AM";
    h = h % 12; if (h === 0) h = 12;
    clockEl.textContent = days[d.getDay()] + "  " + h + ":" + mm + " " + ap;
  }
  tickClock();
  setInterval(tickClock, 15000);
})();
